static File blockFile,strictFile;static uint8_t blockIndex[pocketdns::INDEX_ENTRIES][5],rangeBuffer[pocketdns::MAX_RANGE*5];
static uint32_t blockCount=0,strictCount=0;
static bool fsOkay=false,listsOkay=false,securityOkay=false,apOn=false,connecting=false,webOkay=false,confirmed=false,blocking=true;
static uint32_t pauseUntil=0,connectAt=0,disconnectAt=0,lastSerial=0,restartAt=0,bootHeldAt=0,started=0;
