static void error(int code,const String& message){DynamicJsonDocument d(512);d["error"]=message;String out;serializeJson(d,out);web.send(code,"application/json",out);}
static void json(JsonDocument& d){String s;serializeJson(d,s);web.sendHeader("Cache-Control","no-store");web.send(200,"application/json",s);}
static bool admin(bool mutation=false){if(!auth.admin(web)){error(401,"Please sign in");return false;}if(mutation&&web.header("X-PocketDNS")!="1"){error(403,"Missing request header");return false;}return true;}
static bool statusAccess(){if(auth.admin(web)||auth.bearer(web))return true;error(401,"Please sign in");return false;}
static bool body(JsonDocument& d,size_t limit=24576){String raw=web.arg("plain");if(raw.length()>limit){error(413,"Request is too large");return false;}if(deserializeJson(d,raw)){error(400,"Invalid JSON");return false;}return true;}
static void ok(){web.send(200,"application/json","{\"ok\":true}");}
static const char* resultName(Result r){switch(r){case Result::Blocked:return "blocked";case Result::Cached:return "cached";case Result::Bypass:return "bypass";case Result::Error:return "error";case Result::Portal:return "setup";default:return "allowed";}}
static void getMac(DnsClient& c){if(c.mac[0])return;ip4_addr_t ip;ip.addr=c.ip;struct eth_addr* eth=nullptr;const ip4_addr_t* ret=nullptr;for(netif* n=netif_list;n;n=n->next)if(etharp_find_addr(n,&ip,&eth,&ret)>=0&&eth){snprintf(c.mac,sizeof(c.mac),"%02x:%02x:%02x:%02x:%02x:%02x",eth->addr[0],eth->addr[1],eth->addr[2],eth->addr[3],eth->addr[4],eth->addr[5]);return;}}
static DnsClient* client(uint32_t ip){DnsClient* oldest=&clients[0];for(auto& c:clients){if(c.ip==ip){c.last=millis();getMac(c);return &c;}if(!c.ip)oldest=&c;else if(oldest->ip&&int32_t(c.last-oldest->last)<0)oldest=&c;}*oldest=DnsClient{};oldest->ip=ip;oldest->last=millis();getMac(*oldest);return oldest;}
static const DeviceSetting* device(const DnsClient* c){if(!c)return nullptr;String ip=IPAddress(c->ip).toString();for(unsigned i=0;i<config.deviceCount;i++)if(c->mac[0]&&!strcmp(c->mac,config.devices[i].key))return &config.devices[i];for(unsigned i=0;i<config.deviceCount;i++)if(ip==config.devices[i].key)return &config.devices[i];return nullptr;}
static bool strictContains(uint64_t h){uint32_t lo=0,hi=strictCount;uint8_t b[5];while(lo<hi){uint32_t mid=lo+(hi-lo)/2;if(!strictFile.seek(mid*5)||strictFile.read(b,5)!=5)return false;uint64_t v=pocketdns::unpackHash(b);if(v==h)return true;if(v<h)lo=mid+1;else hi=mid;}return false;}
static bool balancedContains(uint64_t h){return pocketdns::indexedContains(h,blockCount,blockIndex,rangeBuffer,[](uint32_t offset,uint8_t* out,size_t n){return blockFile.seek(offset)&&blockFile.read(out,n)==n;});}
static Decision filter(void*,uint32_t ip,const char* domain){
 if(apOn&&((ip&0x00ffffff)==((uint32_t)WiFi.softAPIP()&0x00ffffff))){Decision d;d.portalAddress=(uint32_t)WiFi.softAPIP();d.reason="setup portal";return d;}
 Decision d;if(!strcmp(domain,"pocketdns.local")||!strcmp(domain,"pocketdns.lan")){d.portalAddress=WiFi.status()==WL_CONNECTED?(uint32_t)WiFi.localIP():(uint32_t)WiFi.softAPIP();d.reason="local dashboard";return d;}
 const auto* dev=ip?device(client(ip)):nullptr;if(dev&&dev->banned){d.blocked=true;d.reason="device DNS disabled";return d;}
 Profile p=dev?dev->profile:config.profile;if(!blocking||p==Profile::Bypass){d.bypass=true;d.reason="filtering paused or bypass profile";return d;}
 if(config.matches(domain,true)){d.reason="allow rule";return d;}if(config.matches(domain,false)){d.blocked=true;d.reason="custom block rule";return d;}
 const char* suffix=domain;while(*suffix){uint64_t h=pocketdns::fnv40(suffix,strlen(suffix));if(balancedContains(h)){d.blocked=true;d.reason="balanced blocklist";return d;}if(p==Profile::Strict&&strictContains(h)){d.blocked=true;d.reason="strict blocklist";return d;}const char* dot=strchr(suffix,'.');if(!dot||!strchr(dot+1,'.'))break;suffix=dot+1;}return d;
}
static void event(void*,const Event& e){
 if(e.internal){if(!strcmp(e.domain,"doubleclick.net"))diagnostic.filtered=e.result==Result::Blocked;if(!strcmp(e.domain,"example.com")){diagnostic.resolved=e.rcode==0&&e.result!=Result::Error;strlcpy(diagnostic.reason,e.reason,sizeof(diagnostic.reason));}return;}
 if(e.result==Result::Portal)return;auto* c=client(e.ip);if(e.result==Result::Blocked)c->blocked++;else c->allowed++;
 if(!config.history)return;auto& h=history[historyNext];h.ip=e.ip;h.at=e.at;h.elapsed=e.elapsed;h.type=e.type;h.result=e.result;h.rcode=e.rcode;h.tcp=e.tcp;h.backup=e.backup;strlcpy(h.domain,e.domain,sizeof(h.domain));strlcpy(h.reason,e.reason,sizeof(h.reason));historyNext=(historyNext+1)%48;historySize=std::min<unsigned>(48,historySize+1);
}
static EngineSettings engineSettings(){EngineSettings e;IPAddress ip;ip.fromString(config.primary);e.primary=(uint32_t)ip;ip.fromString(config.backup);e.backup=(uint32_t)ip;e.useBackup=config.useBackup;return e;}
static bool loadLists(){blockFile=LittleFS.open("/blocklist.bin","r");strictFile=LittleFS.open("/strict.bin","r");if(!blockFile||!strictFile||blockFile.size()%5||strictFile.size()%5)return false;blockCount=blockFile.size()/5;strictCount=strictFile.size()/5;if(!blockCount)return false;for(unsigned i=0;i<pocketdns::INDEX_ENTRIES;i++){uint32_t pos=uint64_t(i)*(blockCount-1)/(pocketdns::INDEX_ENTRIES-1);if(!blockFile.seek(pos*5)||blockFile.read(blockIndex[i],5)!=5)return false;}return true;}
static bool commit(){if(!fsOkay){error(503,"Filesystem unavailable");return false;}if(!store.save(candidate,candidate)){error(507,"Settings could not be saved; previous copy retained");return false;}config=candidate;blocking=config.blocking;pauseUntil=0;dns.configure(engineSettings());if(!config.history){memset(history,0,sizeof(history));historyNext=historySize=0;}return true;}
static void startAP(){if(apOn)return;WiFi.mode(WIFI_AP_STA);WiFi.softAPConfig(IPAddress(192,168,4,1),IPAddress(192,168,4,1),IPAddress(255,255,255,0));apOn=WiFi.softAP(setupSsid.c_str(),auth.setupPassword.c_str());lastSerial=0;}
static void announce(){if(!apOn||uint32_t(millis()-lastSerial)<5000)return;lastSerial=millis();DynamicJsonDocument d(256);d["pocketdns_setup"]=2;d["ssid"]=setupSsid;d["password"]=auth.setupPassword;d["url"]="http://192.168.4.1";String s;serializeJson(d,s);serialLine(s);}
static void connectWiFi(const String& ssid,const String& pass){WiFi.mode(apOn?WIFI_AP_STA:WIFI_STA);WiFi.setSleep(false);WiFi.setHostname("pocketdns");WiFi.begin(ssid.c_str(),pass.c_str());connecting=true;connectAt=millis();}
static void networkPoll(){
 if(WiFi.status()==WL_CONNECTED){if(connecting){connecting=false;disconnectAt=0;dns.invalidate();MDNS.end();MDNS.begin("pocketdns");MDNS.addService("http","tcp",80);MDNS.addService("domain","udp",53);serialLine(String("Pocket DNS dashboard: http://")+WiFi.localIP().toString());}if(apOn&&auth.configured()&&uint32_t(millis()-connectAt)>90000){WiFi.softAPdisconnect(true);WiFi.mode(WIFI_STA);apOn=false;}}
 else{if(!disconnectAt)disconnectAt=millis();if((connecting&&uint32_t(millis()-connectAt)>20000)||uint32_t(millis()-disconnectAt)>30000){startAP();connecting=false;}if(!connecting&&uint32_t(millis()-connectAt)>60000){Preferences p;p.begin("wifi",true);String ssid=p.getString("ssid",""),pass=p.getString("pass","");p.end();if(ssid.length())connectWiFi(ssid,pass);}}
 announce();
}
static void servePage(const uint8_t* page,size_t n){web.sendHeader("Content-Encoding","gzip");web.sendHeader("Cache-Control","no-store");web.sendHeader("Content-Security-Policy","default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'");web.sendHeader("X-Content-Type-Options","nosniff");web.send_P(200,"text/html",(const char*)page,n);}
static void status(){if(!statusAccess())return;DynamicJsonDocument d(3072);const auto& m=dns.metrics();d["version"]=PDNS_VERSION;d["board"]=PDNS_LAYOUT;d["ip"]=WiFi.localIP().toString();d["ssid"]=WiFi.SSID();d["connected"]=WiFi.status()==WL_CONNECTED;d["blocking"]=blocking;d["resume_seconds"]=pauseUntil?std::max<int32_t>(0,int32_t(pauseUntil-millis()))/1000:0;d["uptime"]=millis()/1000;d["queries"]=m.queries;d["blocked"]=m.blocked;d["allowed"]=m.allowed;d["failed"]=m.failed;d["cache_hits"]=dns.cache().hits;d["cache_entries"]=dns.cache().count(millis());d["backup_used"]=m.backupUsed;d["tcp_used"]=m.tcpUsed;d["pending"]=dns.pending();d["latency_ms"]=m.answered?double(m.latencyTotal)/m.answered:0;d["free_heap"]=ESP.getFreeHeap();d["min_heap"]=ESP.getMinFreeHeap();d["rssi"]=WiFi.RSSI();d["domains"]=blockCount;d["strict_extra"]=strictCount;d["fs_ok"]=fsOkay;d["lists_ok"]=listsOkay;d["dns_ok"]=dns.running();d["startup_confirmed"]=confirmed;d["ha_enabled"]=auth.hasHa();d["settings_revision"]=store.revision();d["setup_ap"]=apOn;json(d);}
static void historyApi(){if(!admin())return;web.setContentLength(CONTENT_LENGTH_UNKNOWN);web.send(200,"application/json","");web.sendContent("{\"entries\":[");for(unsigned i=0;i<historySize;i++){auto& h=history[(historyNext+48-1-i)%48];DynamicJsonDocument d(768);d["domain"]=h.domain;d["ip"]=IPAddress(h.ip).toString();d["age"]=uint32_t(millis()-h.at)/1000;d["result"]=resultName(h.result);d["reason"]=h.reason;d["type"]=h.type;d["ms"]=h.elapsed;d["rcode"]=h.rcode;d["tcp"]=h.tcp;d["backup"]=h.backup;String s;serializeJson(d,s);if(i)web.sendContent(",");web.sendContent(s);dns.poll();}web.sendContent("]}");web.sendContent("");}
static void devicesApi(){if(!admin())return;DynamicJsonDocument d(16384);auto a=d.createNestedArray("devices");for(auto& c:clients){if(!c.ip)continue;auto row=a.createNestedObject();const auto* s=device(&c);row["ip"]=IPAddress(c.ip).toString();row["mac"]=c.mac;row["key"]=c.mac[0]?String(c.mac):IPAddress(c.ip).toString();row["label"]=s?s->label:"";row["profile"]=profileName(s?s->profile:config.profile);row["banned"]=s&&s->banned;row["blocked"]=c.blocked;row["allowed"]=c.allowed;row["age"]=uint32_t(millis()-c.last)/1000;}json(d);}
static void deviceApi(){if(!admin(true))return;DynamicJsonDocument d(768);if(!body(d,1024))return;const char* key=d["key"],*label=d["label"];Profile p;if(!deviceKey(key)||!label||strlen(label)>32||!parseProfile(d["profile"],p)||!d["banned"].is<bool>()){error(400,"Invalid device settings");return;}for(const char* t=label;*t;t++)if(uint8_t(*t)<32){error(400,"Invalid device name");return;}candidate=config;unsigned i=0;for(;i<candidate.deviceCount;i++)if(!strcmp(candidate.devices[i].key,key))break;if(i==candidate.deviceCount){if(i==MAX_DEVICE_SETTINGS){error(400,"32 saved devices maximum");return;}candidate.deviceCount++;}auto& dest=candidate.devices[i];strcpy(dest.key,key);strcpy(dest.label,label);dest.profile=p;dest.banned=d["banned"];if(commit())ok();}
static void ruleApi(){if(!admin(true))return;DynamicJsonDocument d(768);if(!body(d,1024))return;String domain=d["domain"]|"";domain.trim();domain.toLowerCase();if(domain.endsWith("."))domain.remove(domain.length()-1);String action=d["action"]|"";bool permitted=String(d["list"]|"")=="allow";if(!pocketdns::validDomain(domain.c_str())||(action!="add"&&action!="remove")){error(400,"Enter a domain such as example.com");return;}candidate=config;candidate.used=candidate.allowCount=candidate.blockCount=0;memset(candidate.pool,0,sizeof(candidate.pool));for(bool a:{true,false}){auto offsets=a?config.allow:config.block;unsigned count=a?config.allowCount:config.blockCount;for(unsigned i=0;i<count;i++){const char* old=config.pool+offsets[i];if(action=="remove"&&a==permitted&&domain==old)continue;if(!candidate.appendRule(old,a)){error(400,"Rule storage full");return;}}}if(action=="add"&&!candidate.appendRule(domain.c_str(),permitted)){error(400,"Rule storage full");return;}if(commit())ok();}
static void blockingApi(){bool bearer=auth.bearer(web);if(!bearer&&!admin(true))return;DynamicJsonDocument d(256);if(!body(d,512))return;if(!d["enabled"].is<bool>()){error(400,"enabled must be true or false");return;}unsigned duration=d["seconds"]|0;if(duration>86400){error(400,"Pause limited to 24 hours");return;}blocking=d["enabled"];pauseUntil=!blocking&&duration?millis()+duration*1000:0;dns.invalidate();ok();}
static void settingsApi(){if(!admin())return;DynamicJsonDocument d(24576);settingsToJson(config,d.to<JsonObject>());json(d);}
static void settingsSave(){if(!admin(true))return;{DynamicJsonDocument d(24576);if(!body(d))return;const char* why;if(!settingsFromJson(d.as<JsonVariantConst>(),candidate,why)){error(400,why);return;}}if(commit())ok();}
static void diagnosticApi(){if(!admin())return;DynamicJsonDocument d(768);d["running"]=diagnostic.running;d["done"]=diagnostic.done;d["filesystem"]=fsOkay;d["blocklist"]=listsOkay;d["dns_listener"]=dns.running();d["wifi"]=WiFi.status()==WL_CONNECTED;d["blocking_test"]=diagnostic.filtered;d["upstream_test"]=diagnostic.resolved;d["reason"]=diagnostic.reason;d["free_heap"]=ESP.getFreeHeap();json(d);}
static void setupState(){DynamicJsonDocument d(768);d["needs_admin"]=!auth.configured();d["setup_ap"]=apOn;d["authenticated"]=auth.admin(web);d["ssid"]=setupSsid;d["connecting"]=connecting;d["connected"]=WiFi.status()==WL_CONNECTED;d["ip"]=WiFi.status()==WL_CONNECTED?WiFi.localIP().toString():String("");d["version"]=PDNS_VERSION;json(d);}
static void provision(){bool first=!auth.configured();if(first){if(!apOn||web.header("X-PocketDNS")!="1"){error(403,"Connect to setup Wi-Fi first");return;}}else if(!admin(true))return;DynamicJsonDocument d(1024);if(!body(d,2048))return;String ssid=d["ssid"]|"",pass=d["wifi_password"]|"",password=d["admin_password"]|"";if(ssid.length()<1||ssid.length()>32||pass.length()>63){error(400,"Check Wi-Fi name and password");return;}if(first&&(password.length()<8||password.length()>64)){error(400,"Choose an admin password of 8–64 characters");return;}Preferences p;if(!p.begin("wifi",false)){error(507,"Cannot save Wi-Fi settings");return;}bool saved=p.putString("ssid",ssid)&&p.putString("pass",pass);p.end();if(!saved||(first&&!auth.setPassword(password))){error(507,"Could not save setup");return;}connectWiFi(ssid,pass);ok();}
static void webSetup(){
 const char* headers[]={"Cookie","Authorization","X-PocketDNS","Origin"};web.collectHeaders(headers,4);
 web.on("/",HTTP_GET,[]{if(!auth.configured()||apOn)servePage(SETUP_GZ,sizeof(SETUP_GZ));else servePage(DASHBOARD_GZ,sizeof(DASHBOARD_GZ));});web.on("/dashboard",HTTP_GET,[]{servePage(DASHBOARD_GZ,sizeof(DASHBOARD_GZ));});web.on("/setup",HTTP_GET,[]{servePage(SETUP_GZ,sizeof(SETUP_GZ));});
 web.on("/api/setup",HTTP_GET,setupState);web.on("/api/setup",HTTP_POST,provision);
 web.on("/api/login",HTTP_POST,[]{if(web.header("X-PocketDNS")!="1"){error(403,"Missing request header");return;}DynamicJsonDocument d(256);if(!body(d,256))return;if(!auth.login(d["password"]|"",web)){error(401,"Password incorrect or login limited; try in one minute");return;}ok();});web.on("/api/logout",HTTP_POST,[]{if(!admin(true))return;auth.logout(web);ok();});
 web.on("/api/status",HTTP_GET,status);web.on("/api/history",HTTP_GET,historyApi);web.on("/api/history/clear",HTTP_POST,[]{if(!admin(true))return;memset(history,0,sizeof(history));historySize=historyNext=0;ok();});web.on("/api/devices",HTTP_GET,devicesApi);web.on("/api/device",HTTP_POST,deviceApi);web.on("/api/rule",HTTP_POST,ruleApi);web.on("/api/blocking",HTTP_POST,blockingApi);web.on("/api/blocking",HTTP_GET,status);web.on("/api/settings",HTTP_GET,settingsApi);web.on("/api/settings",HTTP_POST,settingsSave);
 web.on("/api/backup",HTTP_GET,[]{if(!admin())return;web.sendHeader("Content-Disposition","attachment; filename=Pocket_DNS_Settings.json");settingsApi();});web.on("/api/restore",HTTP_POST,settingsSave);
 web.on("/api/password",HTTP_POST,[]{if(!admin(true))return;DynamicJsonDocument d(512);if(!body(d,512))return;if(!auth.verify(d["current"]|"")){error(403,"Current password incorrect");return;}if(!auth.setPassword(d["password"]|"")){error(400,"Choose 8–64 characters");return;}ok();});
 web.on("/api/ha/create",HTTP_POST,[]{if(!admin(true))return;String token=auth.createHa();if(!token.length()){error(507,"Could not save token");return;}DynamicJsonDocument d(256);d["token"]=token;json(d);});web.on("/api/ha/revoke",HTTP_POST,[]{if(!admin(true))return;if(!auth.revokeHa()){error(507,"Could not revoke token");return;}ok();});
 web.on("/api/diagnostics",HTTP_GET,diagnosticApi);web.on("/api/diagnostics",HTTP_POST,[]{if(!admin(true))return;diagnostic=Diagnostic{};diagnostic.running=true;diagnostic.at=millis();dns.invalidate();dns.internalQuery("doubleclick.net");dns.internalQuery("example.com");ok();});web.on("/api/reboot",HTTP_POST,[]{if(!admin(true))return;ok();restartAt=millis()+500;});web.on("/api/rollback",HTTP_POST,[]{if(!admin(true))return;if(!esp_ota_check_rollback_is_possible()){error(409,"No previous valid firmware available");return;}ok();delay(100);esp_ota_mark_app_invalid_rollback_and_reboot();});
 web.on("/api/update",HTTP_POST,[]{if(!admin(true))return;if(!updater.complete()){error(400,updater.error.length()?updater.error:"Upload a signed .pdu update");return;}ok();restartAt=millis()+1000;},[]{auto& u=web.upload();if(u.status==UPLOAD_FILE_START){if(auth.admin(web)&&web.header("X-PocketDNS")=="1")updater.start();}else if(u.status==UPLOAD_FILE_WRITE){if(auth.admin(web)&&web.header("X-PocketDNS")=="1")updater.feed(u.buf,u.currentSize);dns.poll();esp_task_wdt_reset();}else if(u.status==UPLOAD_FILE_END){if(auth.admin(web))updater.finish();}else if(u.status==UPLOAD_FILE_ABORTED)updater.fail("Upload cancelled");});
 web.onNotFound([]{if(apOn&&web.method()==HTTP_GET){web.sendHeader("Location","http://192.168.4.1/setup");web.send(302,"text/plain","");}else error(404,"Not found");});web.begin();webOkay=true;
}
static void migrate(){for(bool allowed:{true,false}){File f=LittleFS.open(allowed?"/allowed.txt":"/custom.txt","r");if(!f)continue;while(f.available()){String d=f.readStringUntil('\n');d.trim();d.toLowerCase();if(d.length())config.appendRule(d.c_str(),allowed);}f.close();}candidate=config;store.save(candidate,candidate);}
static void resetDevice(){Preferences p;p.begin("wifi",false);p.clear();p.end();auth.reset();LittleFS.remove("/config-a.dat");LittleFS.remove("/config-b.dat");LittleFS.remove("/custom.txt");LittleFS.remove("/allowed.txt");LittleFS.remove("/banned.txt");delay(100);ESP.restart();}
void setup(){
 Serial.begin(115200);
#if ARDUINO_USB_CDC_ON_BOOT
 Serial0.begin(115200);
#endif
 dnsPtr=new(std::nothrow) DnsEngine;if(!dnsPtr){serialLine("Pocket DNS: insufficient memory for DNS engine");delay(500);ESP.restart();}started=millis();pinMode(BOOT_PIN,INPUT_PULLUP);WiFi.persistent(false);WiFi.mode(WIFI_STA);WiFi.setSleep(false);fsOkay=LittleFS.begin(false);securityOkay=auth.begin();uint8_t mac[6];esp_read_mac(mac,ESP_MAC_WIFI_STA);char suffix[7];snprintf(suffix,sizeof(suffix),"%02X%02X%02X",mac[3],mac[4],mac[5]);setupSsid=String("PocketDNS-")+suffix;
 if(fsOkay){if(!store.load(config,candidate))migrate();listsOkay=loadLists();}blocking=config.blocking;Preferences p;p.begin("wifi",true);String ssid=p.getString("ssid",""),pass=p.getString("pass","");p.end();if(!auth.configured()||!ssid.length())startAP();if(ssid.length())connectWiFi(ssid,pass);
 Hooks h;h.clock=[](void*) -> uint32_t{return millis();};h.random=[](void*){return esp_random();};h.filter=filter;h.event=event;dns.begin(engineSettings(),h);webSetup();esp_task_wdt_init(5,true);esp_task_wdt_add(nullptr);serialLine(String("Pocket DNS ")+PDNS_VERSION+" "+PDNS_LAYOUT);serialLine("Hold BOOT for 8 seconds during normal operation to reset setup/settings. Lists are retained.");
}
